function decode(text) {
  return text.split(";").map((encoded) => {
    const values = encoded.split(",").map(Number);
    const ring = new Float64Array(values.length);
    let longitude = 0, latitude = 0;
    let west = Infinity, south = Infinity, east = -Infinity, north = -Infinity;
    for (let i = 0; i < values.length; i += 2) {
      longitude += values[i]; latitude += values[i + 1];
      ring[i] = longitude / 1e5; ring[i + 1] = latitude / 1e5;
      west = Math.min(west, ring[i]); east = Math.max(east, ring[i]);
      south = Math.min(south, ring[i + 1]); north = Math.max(north, ring[i + 1]);
    }
    return { ring, bounds: [west, south, east, north] };
  });
}

